        /// <summary>A value as GDScript's str() shows it.</summary>
        public static string Str1(object? v)
        {
            switch (v)
            {
                case null: return "<null>";
                case string s: return s;
                case char c: return c.ToString();
                default: return Repr(v, top: true);
            }
        }

        static string Repr(object? v, bool top = false)
        {
            switch (v)
            {
                case null: return "<null>";
                case string s: return top ? s : "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";
                case bool b: return b ? "true" : "false";
                case double d: return Num(d);
                case float f: return Num(f);
                case long or int or short or sbyte or byte or ushort or uint or ulong: return Convert.ToString(v, CultureInfo.InvariantCulture)!;
                case decimal m: return m.ToString(CultureInfo.InvariantCulture);
                case Enum e: return Convert.ToInt64(e, CultureInfo.InvariantCulture).ToString(CultureInfo.InvariantCulture);
                case IDictionary dict:
                {
                    if (dict.Count == 0) return "{  }";
                    var parts = new List<string>();
                    foreach (DictionaryEntry kv in dict) parts.Add(Repr(kv.Key) + ": " + Repr(kv.Value));
                    return "{ " + string.Join(", ", parts) + " }";
                }
                case IEnumerable seq when v is IList || v.GetType().Name.StartsWith("PyTuple"):
                {
                    var parts = new List<string>();
                    foreach (var x in seq) parts.Add(Repr(x));
                    return "[" + string.Join(", ", parts) + "]";
                }
                case System.Runtime.CompilerServices.ITuple tup:
                {
                    var parts = new List<string>();
                    for (int i = 0; i < tup.Length; i++) parts.Add(Repr(tup[i]));
                    return "[" + string.Join(", ", parts) + "]";
                }
            }
            return GodotValue(v) ?? v.ToString() ?? "";
        }

        /// <summary>Godot's math structs (Vector2, Color, Rect2, ...) as GDScript prints them: (1.0, 2.0), [P: ..., S: ...].</summary>
        static string? GodotValue(object v)
        {
            var t = v.GetType();
            if (!t.IsValueType || t.Namespace != "Godot") return null;
            string Field(string name)
            {
                var f = t.GetField(name);
                if (f != null) return Repr(f.GetValue(v));
                var p = t.GetProperty(name);
                return p != null ? Repr(p.GetValue(v)) : "?";
            }
            switch (t.Name)
            {
                case "Vector2": case "Vector2I": return $"({Field("X")}, {Field("Y")})";
                case "Vector3": case "Vector3I": return $"({Field("X")}, {Field("Y")}, {Field("Z")})";
                case "Vector4": case "Vector4I": case "Quaternion": return $"({Field("X")}, {Field("Y")}, {Field("Z")}, {Field("W")})";
                case "Color": return $"({Field("R")}, {Field("G")}, {Field("B")}, {Field("A")})";
                case "Rect2": case "Rect2I": return $"[P: {Field("Position")}, S: {Field("Size")}]";
                default: return null;
            }
        }

        /// <summary>A float as Godot's String::num prints it: 14 decimals (fewer for large numbers), trailing zeros dropped, ".0" kept.</summary>
        public static string Num(double d)
        {
            if (double.IsNaN(d)) return "nan";
            if (double.IsInfinity(d)) return d > 0 ? "inf" : "-inf";
            int decimals = 14;
            double abs = Math.Abs(d);
            if (abs > 10) decimals -= (int)Math.Floor(Math.Log10(abs));
            string s = d.ToString(decimals < 0 ? "F6" : "F" + Math.Min(decimals, 32), CultureInfo.InvariantCulture);
            if (s.Contains('.'))
            {
                s = s.TrimEnd('0');
                if (s.EndsWith(".")) s = s.Substring(0, s.Length - 1);
            }
            if (s == "-0") s = "0";
            return s.Contains('.') || s.Contains('e') ? s : s + ".0";
        }

        // ── String % args (String::sprintf) ──

        public static string format(string fmt, object? args)
        {
            var values = args is IList list && !(args is string) ? list.Cast<object?>().ToList() : new List<object?> { args };
            var sb = new StringBuilder();
            int vi = 0;
            object? Next()
            {
                if (vi >= values.Count) throw new ArgumentException("not enough arguments for format string");
                return values[vi++];
            }
            for (int i = 0; i < fmt.Length; i++)
            {
                char c = fmt[i];
                if (c != '%' || i + 1 >= fmt.Length) { sb.Append(c); continue; }
                i++;
                if (fmt[i] == '%') { sb.Append('%'); continue; }
                bool left = false, zero = false, plus = false;
                for (; i < fmt.Length; i++)
                {
                    if (fmt[i] == '-') left = true;
                    else if (fmt[i] == '0') zero = true;
                    else if (fmt[i] == '+') plus = true;
                    else break;
                }
                int width = 0, prec = -1;
                if (i < fmt.Length && fmt[i] == '*') { width = (int)Convert.ToInt64(Next(), CultureInfo.InvariantCulture); i++; }
                else while (i < fmt.Length && char.IsDigit(fmt[i])) width = width * 10 + (fmt[i++] - '0');
                if (i < fmt.Length && fmt[i] == '.')
                {
                    i++;
                    prec = 0;
                    if (i < fmt.Length && fmt[i] == '*') { prec = (int)Convert.ToInt64(Next(), CultureInfo.InvariantCulture); i++; }
                    else while (i < fmt.Length && char.IsDigit(fmt[i])) prec = prec * 10 + (fmt[i++] - '0');
                }
                if (i >= fmt.Length) throw new ArgumentException("incomplete format");
                char conv = fmt[i];
                string body;
                bool numeric = true, negative = false;
                switch (conv)
                {
                    case 'd':
                    case 'i':
                    {
                        long n = ToLong(Next());
                        negative = n < 0;
                        body = (negative ? -(decimal)n : n).ToString(CultureInfo.InvariantCulture);
                        break;
                    }
                    case 'x': case 'X': case 'o':
                    {
                        long n = ToLong(Next());
                        negative = n < 0;
                        ulong a = negative ? (ulong)(-(n + 1)) + 1 : (ulong)n;
                        body = conv == 'o' ? Convert.ToString((long)a, 8) : a.ToString(conv == 'x' ? "x" : "X", CultureInfo.InvariantCulture);
                        break;
                    }
                    case 'f':
                    {
                        double d = Convert.ToDouble(Next(), CultureInfo.InvariantCulture);
                        negative = d < 0 || d == 0 && double.IsNegative(d);
                        double a = Math.Abs(d);
                        body = double.IsInfinity(a) ? "inf" : double.IsNaN(a) ? "nan" : Fixed(a, prec < 0 ? 6 : prec);
                        break;
                    }
                    case 'c':
                    {
                        var v = Next();
                        body = v is string cs ? (cs.Length > 0 ? cs.Substring(0, 1) : "") : char.ConvertFromUtf32((int)ToLong(v));
                        numeric = false;
                        break;
                    }
                    case 's':
                    case 'v':
                        body = Str1(Next());
                        if (prec >= 0 && body.Length > prec) body = body.Substring(0, prec);
                        numeric = false;
                        break;
                    default: throw new ArgumentException($"unsupported format character '{conv}'");
                }
                if (numeric)
                {
                    string sign = negative ? "-" : plus ? "+" : "";
                    int pad = width - sign.Length;
                    if (left) body = sign + body.PadRight(pad);
                    else if (zero) body = sign + body.PadLeft(pad, '0');
                    else body = (sign + body).PadLeft(width);
                }
                else body = left ? body.PadRight(width) : body.PadLeft(width);
                sb.Append(body);
            }
            if (vi < values.Count) throw new ArgumentException("not all arguments converted during string formatting");
            return sb.ToString();
        }

        /// <summary>
        /// a (≥ 0) with prec decimals: its exact decimal value rounded half away from zero, as the Windows C runtime Godot's
        /// official builds use prints it ("%.1f" % 1.25 is 1.3; .NET's own formatting would round the tie to even).
        /// </summary>
        static string Fixed(double a, int prec)
        {
            string exact = a.ToString("F" + (prec + 80), CultureInfo.InvariantCulture);
            int dot = exact.IndexOf('.');
            var digits = (exact.Substring(0, dot) + exact.Substring(dot + 1, prec)).ToCharArray();
            if (exact[dot + 1 + prec] >= '5')
            {
                int k = digits.Length - 1;
                while (k >= 0 && digits[k] == '9') digits[k--] = '0';
                if (k >= 0) digits[k]++;
                else digits = ("1" + new string(digits)).ToCharArray();
            }
            string all = new string(digits);
            int intLen = all.Length - prec;
            return prec == 0 ? all : all.Substring(0, intLen) + "." + all.Substring(intLen);
        }

        static long ToLong(object? v) => v switch
        {
            double d => (long)d,
            float f => (long)f,
            bool b => b ? 1 : 0,
            string s => long.Parse(s, CultureInfo.InvariantCulture),
            _ => Convert.ToInt64(v, CultureInfo.InvariantCulture),
        };

