        public static bool is_equal_approx(double a, double b)
        {
            if (a == b) return true;
            double tolerance = 0.00001 * Math.Abs(a);
            if (tolerance < 0.00001) tolerance = 0.00001;
            return Math.Abs(a - b) < tolerance;
        }
