        public static double ease(double x, double curve)
        {
            if (x < 0) x = 0; else if (x > 1) x = 1;
            if (curve > 0) return curve < 1.0 ? 1.0 - Math.Pow(1.0 - x, 1.0 / curve) : Math.Pow(x, curve);
            if (curve < 0)
            {
                if (x < 0.5) return Math.Pow(x * 2.0, -curve) * 0.5;
                return (1.0 - Math.Pow(1.0 - (x - 0.5) * 2.0, -curve)) * 0.5 + 0.5;
            }
            return 0;
        }

