        // ── random numbers: Godot's PCG32 global generator ──

        static ulong _state, _inc = (1442695040888963407UL << 1) | 1UL;
        static bool _seeded;

        static uint Next32()
        {
            if (!_seeded) randomize();
            ulong old = _state;
            _state = unchecked(old * 6364136223846793005UL + _inc);
            uint xorshifted = (uint)(((old >> 18) ^ old) >> 27);
            int rot = (int)(old >> 59);
            return (xorshifted >> rot) | (xorshifted << ((-rot) & 31));
        }

        public static void seed(long s)
        {
            _seeded = true;
            _inc = (1442695040888963407UL << 1) | 1UL;
            _state = 0;
            Next32();
            _state = unchecked(_state + (ulong)s);
            Next32();
        }

        public static void randomize() => seed(DateTime.UtcNow.Ticks ^ Environment.TickCount64 << 20);

        public static long randi() => Next32();

        static uint Bounded(uint bound)
        {
            uint threshold = unchecked((uint)-bound) % bound;
            while (true) { uint r = Next32(); if (r >= threshold) return r % bound; }
        }

        public static long randi_range(long from, long to)
        {
            if (from == to) return from;
            return Bounded((uint)Math.Abs(from - to) + 1U) + Math.Min(from, to);
        }

        static int Clz32(uint x) => x == 0 ? 32 : System.Numerics.BitOperations.LeadingZeroCount(x);

        public static double randf()
        {
            uint proto = Next32();
            if (proto == 0) return 0;
            return (double)MathF.ScaleB((float)(Next32() | 0x80000001), -32 - Clz32(proto));
        }

        static double Randd()
        {
            uint proto = Next32();
            if (proto == 0) return 0;
            ulong significand = (((ulong)Next32()) << 32) | Next32() | 0x8000000000000001UL;
            return Math.ScaleB((double)significand, -64 - Clz32(proto));
        }

        public static double randf_range(double from, double to) => Randd() * (to - from) + from;

        public static double randfn(double mean, double deviation)
        {
            double t = Randd();
            if (t == 0) t = 1e-300;
            return mean + deviation * (Math.Cos(TAU * Randd()) * Math.Sqrt(-2.0 * Math.Log(t)));
        }

