        public static T pop_back<T>(List<T> xs)
        {
            if (xs.Count == 0) return default!;
            var v = xs[xs.Count - 1];
            xs.RemoveAt(xs.Count - 1);
            return v;
        }

        public static T pop_front<T>(List<T> xs)
        {
            if (xs.Count == 0) return default!;
            var v = xs[0];
            xs.RemoveAt(0);
            return v;
        }

        public static void erase<T>(List<T> xs, T value) { int i = xs.IndexOf(value); if (i >= 0) xs.RemoveAt(i); }
        public static bool erase<K, V>(IDictionary<K, V> d, K key) => d.Remove(key);

        public static long find<T>(List<T> xs, T value) => xs.IndexOf(value);
        public static long find<T>(List<T> xs, T value, long from) => xs.IndexOf(value, (int)(from < 0 ? Math.Max(0, xs.Count + from) : from));
        public static long find(string s, string what) => s.IndexOf(what, StringComparison.Ordinal);
        public static long find(string s, string what, long from) => s.IndexOf(what, (int)from, StringComparison.Ordinal);

        public static void resize<T>(List<T> xs, long size)
        {
            if (size < xs.Count) xs.RemoveRange((int)size, xs.Count - (int)size);
            else while (xs.Count < size) xs.Add(default!);
        }

        public static void fill<T>(List<T> xs, T value) { for (int i = 0; i < xs.Count; i++) xs[i] = value; }

        public static T reduce<T>(List<T> xs, Func<T, T, T> f, T accum)
        {
            foreach (var x in xs) accum = f(accum, x);
            return accum;
        }

        public static T reduce<T>(List<T> xs, Func<T, T, T> f)
        {
            if (xs.Count == 0) return default!;
            T accum = xs[0];
            for (int i = 1; i < xs.Count; i++) accum = f(accum, xs[i]);
            return accum;
        }

        public static void sort_custom<T>(List<T> xs, Func<T, T, bool> less)
        {
            // a stable insertion of each item (GDScript's sort_custom is not stable either, but it never throws on
            // an inconsistent comparator; List.Sort can)
            var copy = xs.ToList();
            copy.Sort((a, b) => less(a, b) ? -1 : less(b, a) ? 1 : 0);
            for (int i = 0; i < xs.Count; i++) xs[i] = copy[i];
        }

        public static bool has_all<T>(List<T> xs, List<T> values) => values.All(xs.Contains);

        public static void merge<K, V>(IDictionary<K, V> d, IDictionary<K, V> other) => merge(d, other, false);
        public static void merge<K, V>(IDictionary<K, V> d, IDictionary<K, V> other, bool overwrite)
        {
            foreach (var kv in other) if (overwrite || !d.ContainsKey(kv.Key)) d[kv.Key] = kv.Value;
        }

        public static string substr(string s, long from) => from >= s.Length ? "" : s.Substring((int)Math.Max(0, from));
        public static string substr(string s, long from, long len)
        {
            if (from < 0) from = 0;
            if (from >= s.Length) return "";
            if (len < 0 || from + len > s.Length) len = s.Length - from;
            return s.Substring((int)from, (int)len);
        }

        public static string left(string s, long n) => n < 0 ? (s.Length + n <= 0 ? "" : s.Substring(0, s.Length + (int)n)) : s.Substring(0, (int)Math.Min(n, s.Length));
        public static string right(string s, long n) => n < 0 ? (s.Length + n <= 0 ? "" : s.Substring((int)-n)) : s.Substring(s.Length - (int)Math.Min(n, s.Length));

        /// <summary>String.to_int(): the leading integer, ignoring what follows ("12abc" → 12, "abc" → 0).</summary>
        public static long str_to_int(string s)
        {
            long v = 0; int i = 0; bool neg = false;
            s = s.Trim();
            if (i < s.Length && (s[i] == '-' || s[i] == '+')) { neg = s[i] == '-'; i++; }
            for (; i < s.Length; i++)
            {
                if (char.IsDigit(s[i])) v = unchecked(v * 10 + (s[i] - '0'));
                else if (s[i] == '.') break;
            }
            return neg ? -v : v;
        }

        public static double str_to_float(string s)
        {
            s = s.Trim();
            int end = 0;
            while (end < s.Length && (char.IsDigit(s[end]) || "+-.eE".IndexOf(s[end]) >= 0)) end++;
            for (int k = end; k > 0; k--)
                if (double.TryParse(s.Substring(0, k), NumberStyles.Float, CultureInfo.InvariantCulture, out var d)) return d;
            return 0.0;
        }

        public static bool is_valid_int(string s) => s.Length > 0 && long.TryParse(s, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out _);
        public static bool is_valid_float(string s) => double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out _);

        public static string pad_zeros(string s, long digits)
        {
            bool neg = s.StartsWith("-");
            string body = neg ? s.Substring(1) : s;
            int dot = body.IndexOf('.');
            int intLen = dot < 0 ? body.Length : dot;
            if (intLen < digits) body = new string('0', (int)digits - intLen) + body;
            return neg ? "-" + body : body;
        }

        /// <summary>String.capitalize(): words split at underscores, spaces and case changes, each capitalized ("hello_world" → "Hello World").</summary>
        public static string capitalize(string s)
        {
            var words = new List<string>();
            var cur = new StringBuilder();
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                if (c == '_' || c == ' ') { if (cur.Length > 0) { words.Add(cur.ToString()); cur.Clear(); } continue; }
                if (char.IsUpper(c) && cur.Length > 0 && char.IsLower(cur[cur.Length - 1])) { words.Add(cur.ToString()); cur.Clear(); }
                cur.Append(c);
            }
            if (cur.Length > 0) words.Add(cur.ToString());
            return string.Join(" ", words.Select(w => char.ToUpperInvariant(w[0]) + w.Substring(1).ToLowerInvariant()));
        }

        // ── statements and objects ──

        public static void assert_(bool condition) { if (!condition) throw new AssertionError("Assertion failed."); }
        public static void assert_(bool condition, string message) { if (!condition) throw new AssertionError("Assertion failed: " + message); }

        /// <summary>load()/preload() without Godot: there are no resources to load.</summary>
        public static object? load(string path) => throw new InvalidOperationException($"load(\"{path}\") needs Godot");

        /// <summary>quit() of a SceneTree script run without Godot: the script runs to the end of _init anyway.</summary>
        public static void quit() { }
        public static void quit(long exitCode) { Environment.ExitCode = (int)exitCode; }

        /// <summary>A signal: callables connected to it are called by emit(), in the order they were connected.</summary>
        public sealed class GdSignal
        {
            readonly List<object> _handlers = new List<object>();
            public void connect(object f) => _handlers.Add(f);
            public void connect(object f, long flags) => _handlers.Add(f);
            public void connect(Delegate f) => _handlers.Add(f);
            public void disconnect(object f) => _handlers.Remove(f);
            public void disconnect(Delegate f) => _handlers.Remove(f);
            public bool is_connected(object f) => _handlers.Contains(f);
            public bool is_connected(Delegate f) => _handlers.Contains(f);
            public void emit(params object?[] args) { foreach (var h in _handlers.ToArray()) Builtins.__invoke(h, args); }
            public long get_connections_count() => _handlers.Count;
        }

        public static GdSignal Signal() => new GdSignal();
    }
}
